import json
import heapq

with open("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/graph.json") as f:
    data = json.load(f)

nodes = data["nodes"]
edges = data["edges"]

adj = {node: [] for node in nodes}
for e in edges:
    u, v, w = e["from"], e["to"], e["weight"]
    adj[u].append((v, w))
    adj[v].append((u, w))

INF = float('inf')
dist = {node: INF for node in nodes}
dist["A"] = 0

heap = [(0, "A")]
visited = set()

while heap:
    d, u = heapq.heappop(heap)
    if u in visited:
        continue
    visited.add(u)
    for v, w in adj[u]:
        if v not in visited:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

print("=== Shortest Paths from A ===")
print()
for node in sorted(nodes):
    d = dist[node]
    if d == INF:
        print(f"A -> {node}: unreachable")
    elif d == int(d):
        print(f"A -> {node}: {int(d)}")
    else:
        print(f"A -> {node}: {d}")

