import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/graph.json';
    const data = fs.readFileSync(filePath, 'utf-8');
    const graph: Graph = JSON.parse(data);

    const nodes: string[] = graph.nodes;
    const edges: Edge[] = graph.edges;

    // Build adjacency list (undirected graph)
    const adj: Map<string, Map<string, number>> = new Map();
    for (const node of nodes) {
        adj.set(node, new Map());
    }
    for (const edge of edges) {
        if (!adj.has(edge.from)) adj.set(edge.from, new Map());
        if (!adj.has(edge.to)) adj.set(edge.to, new Map());
        const existing = adj.get(edge.from)!.get(edge.to);
        if (existing === undefined || edge.weight < existing) {
            adj.get(edge.from)!.set(edge.to, edge.weight);
            adj.get(edge.to)!.set(edge.from, edge.weight);
        }
    }

    // Dijkstra's algorithm
    const dist: Map<string, number> = new Map();
    const visited: Set<string> = new Set();

    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    for (let i = 0; i < nodes.length; i++) {
        // Find unvisited node with minimum distance
        let minDist = Infinity;
        let minNode: string | null = null;
        for (const node of nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null) break;

        visited.add(minNode);

        // Relax edges from minNode
        const neighbors = adj.get(minNode)!;
        for (const [neighbor, weight] of neighbors) {
            if (!visited.has(neighbor)) {
                const newDist = dist.get(minNode)! + weight;
                if (newDist < dist.get(neighbor)!) {
                    dist.set(neighbor, newDist);
                }
            }
        }
    }

    // Output
    console.log('=== Shortest Paths from A ===');
    console.log('');

    const sorted = [...nodes].sort();
    for (const node of sorted) {
        const d = dist.get(node)!;
        if (d === Infinity) {
            console.log(`A -> ${node}: unreachable`);
        } else {
            console.log(`A -> ${node}: ${d}`);
        }
    }
}

main();

