const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
  const match = line.match(regex);
  if (!match) continue;

  const [, , hour, level, component, message] = match;

  levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

  if (level === 'ERROR') {
    errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
    errorMessages.add(message);
  }

  hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');

const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
  out.push(`  ${level}: ${count}`);
}

out.push('');

let maxErrComponent = '';
let maxErrCount = -1;
const sortedErrComps = [...errorComponentCounts.entries()].sort((a, b) => {
  if (b[1] !== a[1]) return b[1] - a[1];
  return a[0].localeCompare(b[0]);
});
if (sortedErrComps.length > 0) {
  maxErrComponent = sortedErrComps[0][0];
  maxErrCount = sortedErrComps[0][1];
}
out.push(`Component with Most Errors: ${maxErrComponent} (${maxErrCount} errors)`);

out.push('');
out.push('Unique Error Messages:');

const sortedMessages = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMessages) {
  out.push(`  - ${msg}`);
}

out.push('');

let busiestHour = '';
let busiestCount = -1;
const sortedHours = [...hourCounts.entries()].sort((a, b) => {
  if (b[1] !== a[1]) return b[1] - a[1];
  return a[0].localeCompare(b[0]);
});
if (sortedHours.length > 0) {
  busiestHour = sortedHours[0][0];
  busiestCount = sortedHours[0][1];
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

