use std::collections::{BTreeMap, BTreeSet};
use std::fs;

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/app.log";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = match line.find(']') {
            Some(pos) => pos,
            None => continue,
        };

        // timestamp is between [ and ]
        let timestamp = &line[1..close_bracket];

        let rest = line[close_bracket + 1..].trim_start();

        let open_paren = match rest.find('(') {
            Some(pos) => pos,
            None => continue,
        };
        let level = rest[..open_paren].trim().to_string();

        let after_open = &rest[open_paren + 1..];
        let close_paren = match after_open.find(')') {
            Some(pos) => pos,
            None => continue,
        };
        let component = after_open[..close_paren].to_string();

        let after_close = after_open[close_paren + 1..].trim_start();
        let message = if let Some(stripped) = after_close.strip_prefix("- ") {
            stripped.to_string()
        } else if let Some(stripped) = after_close.strip_prefix('-') {
            stripped.trim_start().to_string()
        } else {
            after_close.to_string()
        };

        // Count by level
        *level_counts.entry(level.clone()).or_insert(0) += 1;

        // Hour from timestamp "YYYY-MM-DD HH:MM:SS"
        if timestamp.len() >= 13 {
            if let Ok(hour) = timestamp[11..13].parse::<u32>() {
                *hour_counts.entry(hour).or_insert(0) += 1;
            }
        }

        // Track errors
        if level == "ERROR" {
            *error_component_counts.entry(component.clone()).or_insert(0) += 1;
            error_messages.insert(message.clone());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(k, v)| (k.clone(), *v))
        .unwrap_or_else(|| ("N/A".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

