#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd)
{
    size_t cap = 4096;
    char *buffer = malloc(cap);
    if (!buffer)
        return NULL;

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        free(buffer);
        return NULL;
    }

    size_t total = 0;
    size_t n;
    while ((n = fread(buffer + total, 1, cap - total, fp)) > 0) {
        total += n;
        if (total == cap) {
            cap *= 2;
            char *tmp = realloc(buffer, cap);
            if (!tmp) {
                free(buffer);
                pclose(fp);
                return NULL;
            }
            buffer = tmp;
        }
    }
    pclose(fp);

    buffer[total] = '\0';

    while (total > 0 &&
           (buffer[total - 1] == '\n' ||
            buffer[total - 1] == '\r' ||
            buffer[total - 1] == ' '  ||
            buffer[total - 1] == '\t')) {
        buffer[--total] = '\0';
    }

    return buffer;
}

