fn format_commas(n: i64) -> String {
    let negative = n < 0;
    let abs_n = if negative { -n } else { n };
    let s = abs_n.to_string();
    let len = s.len();
    let mut result = String::new();
    if negative {
        result.push('-');
    }
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    result
}

