            while (end < obj.length()) {
                if (obj.charAt(end) == '\\') { end += 2; continue; }
                if (obj.charAt(end) == '"') break;
                end++;
            }
            if (end < obj.length()) {
                return obj.substring(idx, end);
            }
        }
        return null;
    }

    static String extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return null;
        idx += search.length();
        while (idx < obj.length() && (obj.charAt(idx) == ' ' || obj.charAt(idx) == '\t' || obj.charAt(idx) == ':')) idx++;
