use std::process::Command;

fn run_cmd(cmd: &str) -> String {
    let output = Command::new(cmd)
        .output()
        .unwrap_or_else(|e| panic!("failed to execute '{}': {}", cmd, e));
    let stdout = String::from_utf8_lossy(&output.stdout);
    stdout.trim().to_string()
}

fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out
}

fn main() {
    let hostname = run_cmd("hostname");
    let os = run_cmd("uname -s");
    let architecture = run_cmd("uname -m");
    let username = run_cmd("whoami");

    let json = format!(
        "{{\n  \"hostname\": \"{}\",\n  \"os\": \"{}\",\n  \"architecture\": \"{}\",\n  \"username\": \"{}\"\n}}",
        json_escape(&hostname),
        json_escape(&os),
        json_escape(&architecture),
        json_escape(&username)
    );
    print!("{}", json);
}

