import * as http from "http";

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

function main(): void {
  const req = http.request(
    {
      hostname: "127.0.0.1",
      port: 18924,
      path: "/api/products",
      method: "GET",
    },
    (res: any) => {
      let data = "";
      res.on("data", (chunk: any) => {
        data += chunk.toString();
      });
      res.on("end", () => {
        const products: Product[] = JSON.parse(data);
        const filtered = products.filter((p: Product) => p.price > 50.0);
        filtered.sort((a: Product, b: Product) => a.name.localeCompare(b.name));

        const out: string[] = [];
