let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

for line in lines {
    guard line.hasPrefix("[") else { continue }
    guard let closeBracket = line.firstIndex(of: "]") else { continue }

    let timestamp = String(line[line.index(after: line.startIndex)..<closeBracket])
    let tsArray = Array(timestamp)
    guard tsArray.count >= 13 else { continue }
    let hour = String(tsArray[11...12])

    let rest = String(line[line.index(after: closeBracket)...])
    let restTrimmed = rest.trimmingCharacters(in: .whitespaces)

    guard let openParen = restTrimmed.firstIndex(of: "(") else { continue }
    let level = restTrimmed[restTrimmed.startIndex..<openParen].trimmingCharacters(in: .whitespaces)

    let afterOpen = restTrimmed[restTrimmed.index(after: openParen)...]
    guard let closeParen = afterOpen.firstIndex(of: ")") else { continue }
    let component = String(afterOpen[afterOpen.index(after: afterOpen.startIndex)..<closeParen])

    let afterClose = String(afterOpen[afterOpen.index(after: closeParen)...])
    guard afterClose.hasPrefix(" - ") else { continue }
    let message = String(afterClose.dropFirst(3))

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

