import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {

    static abstract class JsonValue {
        abstract String canonical();
        abstract void write(StringBuilder sb, int indent);
    }

    static class JsonObject extends JsonValue {
        TreeMap<String, JsonValue> map = new TreeMap<>();

        @Override
        public String canonical() {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, JsonValue> e : map.entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append('"').append(escape(e.getKey())).append("\":").append(e.getValue().canonical());
            }
            sb.append('}');
            return sb.toString();
        }

        @Override
        public void write(StringBuilder sb, int indent) {
            if (map.isEmpty()) {
                sb.append("{}");
                return;
            }
            sb.append("{\n");
            String pad = "  ".repeat(indent + 1);
            String padOuter = "  ".repeat(indent);
            boolean first = true;
            for (Map.Entry<String, JsonValue> e : map.entrySet()) {
                if (!first) sb.append(",\n");
                first = false;
                sb.append(pad).append('"').append(escape(e.getKey())).append("\": ");
                e.getValue().write(sb, indent + 1);
            }
            sb.append('\n').append(padOuter).append('}');
        }
    }

    static class JsonArray extends JsonValue {
        List<JsonValue> list = new ArrayList<>();

        @Override
        public String canonical() {
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (JsonValue v : list) {
                if (!first) sb.append(',');
                first = false;
                sb.append(v.canonical());
            }
            sb.append(']');
            return sb.toString();
        }

        @Override
        public void write(StringBuilder sb, int indent) {
            if (list.isEmpty()) {
                sb.append("[]");
                return;
            }
            sb.append("[\n");
            String pad = "  ".repeat(indent + 1);
            String padOuter = "  ".repeat(indent);
            boolean first = true;
            for (JsonValue v : list) {
                if (!first) sb.append(",\n");
                first = false;
                sb.append(pad);
                v.write(sb, indent + 1);
            }
            sb.append('\n').append(padOuter).append(']');
        }
    }

    static class JsonString extends JsonValue {
        String val;
        JsonString(String val) { this.val = val; }
        @Override
        public String canonical() { return "\"" + escape(val) + "\""; }
        @Override
        public void write(StringBuilder sb, int indent) { sb.append('"').append(escape(val)).append('"'); }
    }

    static class JsonNumber extends JsonValue {
        String val;
        JsonNumber(String val) { this.val = val; }
        @Override
        public String canonical() { return val; }
        @Override
        public void write(StringBuilder sb, int indent) { sb.append(val); }
    }

    static class JsonBoolean extends JsonValue {
        boolean val;
        JsonBoolean(boolean val) { this.val = val; }
        @Override
        public String canonical() { return val ? "true" : "false"; }
        @Override
        public void write(StringBuilder sb, int indent) { sb.append(val ? "true" : "false"); }
    }

    static class JsonNull extends JsonValue {
        @Override
        public String canonical() { return "null"; }
        @Override
        public void write(StringBuilder sb, int indent) { sb.append("null"); }
    }

    static String escape(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    static class JsonParser {
        String src;
        int pos;

