import * as path from 'path';

const rootDir = '/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/project_tree';

interface FileStats {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buf: Buffer): number {
  if (buf.length === 0) return 0;
  let newlineCount = 0;
  for (let i = 0; i < buf.length; i++) {
    if (buf[i] === 10) newlineCount++;
  }
  if (buf[buf.length - 1] === 10) return newlineCount;
  return newlineCount + 1;
}

function walkDir(dir: string, root: string, visited: Set<string>): Map<string, FileStats[]> {
  const result = new Map<string, FileStats[]>();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return result;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      const resolved = fs.realpathSync(fullPath);
      if (visited.has(resolved)) continue;
      visited.add(resolved);

      const subResults = walkDir(fullPath, root, visited);
      for (const [ext, files] of subResults) {
        if (!result.has(ext)) result.set(ext, []);
        result.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      const content = fs.readFileSync(fullPath);
      const chars = content.length;
      const lines = countLines(content);
      const ext = path.extname(entry.name);

      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }

  return result;
}

