    static void walk(Path dir, Path root, Map<String, List<String[]>> extMap, Set<String> visitedDirs) throws IOException {
        File[] files = dir.toFile().listFiles();
        if (files == null) return;

        Arrays.sort(files, Comparator.comparing(File::getName));

        for (File file : files) {
            Path filePath = file.toPath();
            if (Files.isSymbolicLink(filePath)) {
                continue;
            }
            if (Files.isDirectory(filePath)) {
                String dirPath = filePath.toAbsolutePath().normalize().toString();
                if (visitedDirs.contains(dirPath)) continue;
                visitedDirs.add(dirPath);
                walk(filePath, root, extMap, visitedDirs);
            } else if (Files.isRegularFile(filePath)) {
                String relativePath = root.relativize(filePath).toString().replace('\\', '/');

                String fileName = file.getName();
                String ext;
                int dotIdx = fileName.lastIndexOf('.');
                if (dotIdx > 0 && dotIdx < fileName.length() - 1) {
                    ext = fileName.substring(dotIdx);
                } else {
                    ext = "(no extension)";
                }

                long chars = Files.size(filePath);
                long lines = countLines(filePath);

                String[] entry = {relativePath, String.valueOf(lines), String.valueOf(chars)};
                extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(entry);
            }
        }
    }

    static long countLines(Path file) throws IOException {
        long lines = 0;
        boolean lastWasNewline = false;
        boolean hasContent = false;
        try (InputStream is = Files.newInputStream(file)) {
            int c;
            while ((c = is.read()) != -1) {
                hasContent = true;
                if (c == '\n') {
                    lines++;
                    lastWasNewline = true;
                } else {
                    lastWasNewline = false;
                }
            }
        }
        if (hasContent && !lastWasNewline) {
            lines++;
        }
        return lines;
    }
}

