use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn walk(dir: &Path, base: &Path, results: &mut Vec<(String, u64, u64)>) -> Result<(), Box<dyn std::error::Error>> {
    let entries = fs::read_dir(dir)?;
    for entry in entries {
        let entry = entry?;
        let path = entry.path();

        if path.is_symlink() {
            continue;
        }

        if path.is_dir() {
            walk(&path, base, results)?;
        } else if path.is_file() {
            let mut contents = Vec::new();
            let mut file = fs::File::open(&path)?;
            file.read_to_end(&mut contents)?;

            let char_count = contents.len() as u64;

            let line_count: u64 = if contents.is_empty() {
                0
            } else {
                let newlines = contents.iter().filter(|&&b| b == b'\n').count() as u64;
                if contents[contents.len() - 1] != b'\n' {
                    newlines + 1
                } else {
                    newlines
                }
            };

            let rel = path.strip_prefix(base).unwrap();
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            results.push((rel_str, line_count, char_count));
        }
    }
    Ok(())
}

fn main() {
    let base = Path::new("/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/project_tree");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(base, base, &mut files).expect("Failed to walk directory");

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (rel, lines, chars) in &files {
        let path = Path::new(rel);
        let ext = path
            .extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| String::new());
        groups.entry(ext).or_default().push((rel.clone(), *lines, *chars));
    }

    for group in groups.values_mut() {
        group.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, group) in &groups {
        let file_count = group.len() as u64;
        let lines: u64 = group.iter().map(|f| f.1).sum();
