use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;
use std::fs;

enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(entries) = self {
            for (k, v) in entries {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }

    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self {
            Some(s)
        } else {
            None
        }
    }

    fn as_f64(&self) -> Option<f64> {
        if let Json::Num(n) = self {
            Some(*n)
        } else {
            None
        }
    }

    fn as_arr(&self) -> Option<&Vec<Json>> {
        if let Json::Arr(a) = self {
            Some(a)
        } else {
            None
        }
    }
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser {
            chars: s.chars().collect(),
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        if self.pos >= self.chars.len() {
            return Json::Null;
        }
        let c = self.chars[self.pos];
        match c {
            '{' => self.parse_obj(),
            '[' => self.parse_arr(),
            '"' => Json::Str(self.parse_str()),
            't' => {
                self.pos += 4;
                Json::Bool(true)
            }
            'f' => {
                self.pos += 5;
                Json::Bool(false)
            }
            'n' => {
                self.pos += 4;
                Json::Null
            }
            _ => self.parse_num(),
        }
    }

    fn parse_obj(&mut self) -> Json {
        self.pos += 1; // skip {
        self.skip_whitespace();
        let mut entries = Vec::new();
        if self.pos < self.chars.len() && self.chars[self.pos] == '}' {
            self.pos += 1;
            return Json::Obj(entries);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_str();
            self.skip_whitespace();
            self.pos += 1; // skip :
            self.skip_whitespace();
            let val = self.parse();
            entries.push((key, val));
            self.skip_whitespace();
            if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                self.pos += 1;
            } else {
                self.pos += 1; // skip }
                break;
            }
        }
        Json::Obj(entries)
    }

    fn parse_arr(&mut self) -> Json {
        self.pos += 1; // skip [
        self.skip_whitespace();
        let mut items = Vec::new();
        if self.pos < self.chars.len() && self.chars[self.pos] == ']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            self.skip_whitespace();
            let val = self.parse();
            items.push(val);
            self.skip_whitespace();
            if self.pos < self.chars.len() && self.chars[self.pos] == ',' {
                self.pos += 1;
            } else {
                self.pos += 1; // skip ]
                break;
            }
        }
        Json::Arr(items)
    }

    fn parse_str(&mut self) -> String {
        self.pos += 1; // skip opening "
        let mut s = String::new();
        loop {
            if self.pos >= self.chars.len() {
                break;
            }
            let c = self.chars[self.pos];
            self.pos += 1;
            if c == '"' {
                break;
            }
            if c == '\\' {
                let next = self.chars[self.pos];
                self.pos += 1;
                match next {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'n' => s.push('\n'),
                    't' => s.push('\t'),
                    'r' => s.push('\r'),
                    'b' => s.push('\u{8}'),
                    'f' => s.push('\u{c}'),
                    'u' => {
                        let hex: String = self.chars[self.pos..self.pos + 4].iter().collect();
                        self.pos += 4;
                        let code = u32::from_str_radix(&hex, 16).unwrap_or(0xFFFD);
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => s.push(next),
                }
            } else {
                s.push(c);
            }
        }
        s
    }

    fn parse_num(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Num(s.parse::<f64>().unwrap_or(0.0))
    }
}

fn fmt_num(n: f64) -> String {
    if n == n.trunc() && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn main() {
    let path = "/var/folders/cy/wjncqll968nbq194ybzdgt_h0000gn/T/langbench_v1_cp4ar151/graph.json";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = Parser::new(&content);
    let json = parser.parse();

    // Extract nodes
    let mut nodes: Vec<String> = Vec::new();
    if let Some(arr) = json.get("nodes").and_then(|v| v.as_arr()) {
        for item in arr {
            if let Some(s) = item.as_str() {
                nodes.push(s.to_string());
            }
        }
    }

    // Extract edges and build adjacency list (undirected)
    let mut adj: HashMap<String, Vec<(String, f64)>>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).insert(Vec::new());
    }

    if let Some(arr) = json.get("edges").and_then(|v| v.as_arr()) {
        for edge in arr {
            let from = edge.get("from").and_then(|v| v.as_str()).unwrap().to_string();
            let to = edge.get("to").and_then(|v| v.as_str()).unwrap().to_string();
            let weight = edge.get("weight").and_then(|v| v.as_f64()).unwrap_or(0.0);

            adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), weight));
            adj.entry(to).or_insert_with(Vec::new).push((from, weight));
        }
    }

    // Dijkstra's algorithm from "A"
    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    // Min-heap: (distance, node)
    let mut heap: BinaryHeap<Reverse<(f64, String)>> = BinaryHeap::new();
    heap.push(Reverse((0.0, source.clone())));

    while let Some(Reverse((d, node))) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(f64::INFINITY) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                let current = dist.get(neighbor).copied().unwrap_or(f64::INFINITY);
                if new_dist < current {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(Reverse((new_dist, neighbor.clone())));
                }
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in &sorted_nodes {
        let d = dist.get(*node).copied().unwrap_or(f64::INFINITY);
        if d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else {
            println!("A -> {}: {}", node, fmt_num(d));
        }
    }
}

