                                s.push('\u{FFFD}');
                            } else {
                                s.push(char::from_u32(hi).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => return Err("Invalid escape sequence".into()),
                    }
                }
                Some(b) => {
                    if b < 0x80 {
                        s.push(b as char);
                    } else if b >= 0xC0 && b < 0xE0 {
                        let b2 = self.advance().ok_or("Invalid UTF-8")?;
                        let cp = ((b as u32 & 0x1F) << 6) | (b2 as u32 & 0x3F);
                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    } else if b >= 0xE0 && b < 0xF0 {
                        let b2 = self.advance().ok_or("Invalid UTF-8")?;
                        let b3 = self.advance().ok_or("Invalid UTF-8")?;
                        let cp = ((b as u32 & 0x0F) << 12) | ((b2 as u32 & 0x3F) << 6) | (b3 as u32 & 0x3F);
                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    } else if b >= 0xF0 && b < 0xF8 {
                        let b2 = self.advance().ok_or("Invalid UTF-8")?;
                        let b3 = self.advance().ok_or("Invalid UTF-8")?;
                        let b4 = self.advance().ok_or("Invalid UTF-8")?;
                        let cp = ((b as u32 & 0x07) << 18) | ((b2 as u32 & 0x3F) << 12) | ((b3 as u32 & 0x3F) << 6) | (b4 as u32 & 0x3F);
                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    } else {
                        s.push('\u{FFFD}');
                    }
                }
            }
        }
        Ok(s)
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        let mut code = 0u32;
        for _ in 0..4 {
            let c = self.advance().ok_or("Unexpected end in \\u escape")?;
            let d = (c as char).to_digit(16).ok_or("Invalid hex digit in \\u escape")?;
            code = code * 16 + d;
        }
        Ok(code)
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.advance();
        }
        while self.peek().map_or(false, |c| c.is_ascii_digit()) {
            self.advance();
        }
        if self.peek() == Some(b'.') {
            self.advance();
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.advance();
            }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            self.advance();
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') {
                self.advance();
            }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) {
                self.advance();
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|e| e.to_string())?;
        s.parse::<f64>().map(Json::Number).map_err(|e| format!("Invalid number '{}': {}", s, e))
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\x08' => result.push_str("\\b"),
            '\x0C' => result.push_str("\\f"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn format_number(n: f64) -> String {
    if n.is_infinite() || n.is_nan() {
        return "null".to_string();
    }
    if n == n.floor() && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format_number(*n),
        Json::Str(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let items: Vec<String> = arr.iter()
                .map(|v| format!("{}{}", pad_inner, serialize(v, indent + 1)))
                .collect();
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let items: Vec<String> = map.iter()
                .map(|(k, v)| format!("{}\"{}\": {}", pad_inner, escape_string(k), serialize(v, indent + 1)))
                .collect();
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn deep_merge(a: &Json, b: &Json) -> Json {
    match (a, b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = BTreeMap::new();
            for (k, v) in a_map {
                result.insert(k.clone(), v.clone());
            }
            for (k, v) in b_map {
                if let Some(a_v) = a_map.get(k) {
                    result.insert(k.clone(), deep_merge(a_v, v));
                } else {
                    result.insert(k.clone(), v.clone());
                }
            }
            Json::Object(result)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut result = a_arr.clone();
            for item in b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        _ => b.clone(),
    }
}

